// один проход поразрядной: устойчиво раскладывает src в dst по байту shift
static void RadixPass(ulong[] src, ulong[] dst, int n, int shift) {
    Span<int> count = stackalloc int[257];
    for (int i = 0; i < n; i++) count[(int)((src[i] >> shift) & 0xFF) + 1]++;
    for (int b = 0; b < 256; b++) count[b + 1] += count[b];   // count[b] — первая позиция байта b
    for (int i = 0; i < n; i++)                               // слева направо — устойчиво
        dst[count[(int)((src[i] >> shift) & 0xFF)]++] = src[i];
}
// вся сортировка: shift = 0, 8, …, 56, каждый раз меняя src и dst местами

